def block(y,x,b,c):
 for dy in range(5):
  for dx in range(5): g[y+dy][x+dx]=c if 1<=dy<=3 and 1<=dx<=3 else b
for y,x,b,c in [(3,0,8,6),(5,17,2,5),(9,7,2,4),(12,12,8,7),(16,0,8,2),(17,17,2,6)]: block(y,x,b,c)
print('\n'.join(' '.join(map(str,r)) for r in g))

